from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    cache = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        if key not in cache:
            return True
        _, wt = cache[key]
        return t >= wt + ttl

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in cache:
                if is_expired(key, t):
                    # treat as absent, remove expired entry first
                    del cache[key]
                else:
                    # existing valid entry, update value/time, move to end
                    del cache[key]
                    cache[key] = (value, t)
                    continue

            # key is absent now (either never existed or was expired and removed)
            if len(cache) >= capacity:
                # evict LRU
                cache.popitem(last=False)
            cache[key] = (value, t)

        elif kind == 'get':
            if key in cache and not is_expired(key, t):
                value, wt = cache[key]
                del cache[key]
                cache[key] = (value, wt)
                results.append(value)
            else:
                if key in cache:
                    del cache[key]
                results.append(-1)

    return results

